"""П-42 v2: отчёт `docs/findings/p42-level-breakout-v2-2026-11-14.md` из JSON-результатов (числа не набираются руками).

  P42_ROOT=data/p42v2 P42_OUTS=data/p42v2-lx4out P42_OUTS_OLD=data/p42v2-chk python tools/p42/make_doc_v2.py > docs/findings/p42-level-breakout-v2-2026-11-14.md
Читает: report.json (шаг A, 1м), report-tick-tickfull8.json (шаг B, lat 0, после правки разбора цен), report-tick-tickfull-v7.json (до правки),
report-reentry.json (§13.5, lat 0), report-lat.json (задержки; основное чтение — `_lx4`, §13.4 п. 8), tick-lx4/ (сделки 4 мс),
из P42_OUTS: outsiders-summary.json, outsiders-excl.json, outsiders-{long,short}.csv (тики — клетки `*_lx4`; минутки не менялись).
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(__file__))
import make_stats as MS  # noqa: E402
import persist  # noqa: E402

ROOT = os.environ.get("P42_ROOT", "data/p42v2")
OUTS = os.environ.get("P42_OUTS") or ROOT
TAG = "вход+выход 4"  # основное чтение (§13.4 п. 8, В-157)
TAG200 = "вход+выход 200"  # прежнее основное (§13.4 п. 6), теперь справочно
OWNER157 = "«я те кажется кривую задержку сказал. не 200 мс а 4 мс»"


def J(name, root=None):
    return json.load(open(os.path.join(root or ROOT, name), encoding="utf-8"))


def n(x, d=2, sign=True):
    s = ("%+." + str(d) + "f") % x if sign else ("%." + str(d) + "f") % x
    return s.replace("-", "−").replace(".", ",")


def ci(h):
    return "%s [%s; %s]" % (n(h["mean"]), n(h["lo"]), n(h["hi"]))


def cell(h):
    return "%s, n=%d (%s/сут.)" % (ci(h), h["trades"], n(h["trades_per_day"], 2, False))


def verdict_ru(v):
    return v


SIDE = {"long": "Лонг", "short": "Шорт"}


def table_cands(res, names, title_map):
    out = ["| кандидат | половина A (15.09–14.10) | половина B (15.10–13.11) | вердикт §10 |", "|---|---|---|---|"]
    for k in names:
        c = res["cand"].get(k)
        if not c:
            continue
        a, b = c["halves"]["A"], c["halves"]["B"]
        out.append("| %s | %s | %s | %s |" % (title_map.get(k, k), cell(a), cell(b), c["verdict"]))
    return "\n".join(out)


def main():
    A = J("report.json")
    T = J("report-tick-tickfull8.json")
    T7 = J("report-tick-tickfull-v7.json")
    R = J("report-reentry.json")
    LT = J("report-lat.json")
    OS = J("outsiders-summary.json", OUTS)
    EX = J("outsiders-excl.json", OUTS)
    p = []
    w = p.append
    import csv as _csv
    import excl22_doc as ED
    CHAIN, M_FIN = ED.m_chain()
    MCHECK = ED.m_check_text()

    def lt(side, name, tag=TAG):
        return LT[side]["%s|%s" % (name, tag)]

    def tops(side):
        return "/".join(v["verdict"] for k, v in LT[side].items() if k.startswith("топ-3") and k.endswith("|" + TAG))

    chg = MS.verdict_changes(LT, "long") + MS.verdict_changes(LT, "short")
    chg_txt = "Вердикты при 4 мс **те же, что при 200 мс** (база, перекрёстный, топ-3, оба варианта повторного входа)" if not chg else "Изменились против 200 мс: " + "; ".join(chg)
    pr = persist.rows(os.path.join(OUTS, "outsiders-summary.json"))
    tl = {r["side"]: r for r in pr if r["engine"] == "tick"}
    pl, ps = tl["long"], tl["short"]
    old_d = os.environ.get("P42_OUTS_OLD")
    po = persist.rows(os.path.join(old_d, "outsiders-summary.json")) if old_d and os.path.exists(os.path.join(old_d, "outsiders-summary.json")) else None
    old_s = next(r for r in po if r["side"] == "short" and r["engine"] == "tick") if po else None
    ncell = OS["long|tick"]["cells"]

    w("# П-42 версия 2 (универсум ≥ $12 млн, 566 монет; вход и выходы по сделкам Binance): пробой часового уровня, лонг и шорт отдельно — отчёт (14.11.2026)\n")
    w("**Вердикт одной строкой (измерено, 60 суток 15.09–13.11, $500 на сделку, тариф владельца, проскальзывание 1 bp). Основное чтение шага B — задержка 4 мс на входы и выходы (слова владельца, В-157: %s; отклонение протокола §13.4 п. 8: чтение сменено после счёта шага B по слову владельца). 200 мс («ну давай задержка будет 0.2», прежнее основное), 250, 1000 и lat 0 — справочно; lat 0 физически невыполним: 55–64 %% входов в ту же миллисекунду, что сделка-сигнал:**" % OWNER157)
    la, lb = T["long"]["cand"]["base"]["halves"]["A"], T["long"]["cand"]["base"]["halves"]["B"]
    sa, sb = T["short"]["cand"]["base"]["halves"]["A"], T["short"]["cand"]["base"]["halves"]["B"]
    lb0 = lt("long", "база")["halves"]
    sb0 = lt("short", "база")["halves"]
    w("- **Лонг: на минутках опровергнуто (устойчиво), на сделках при реализуемой задержке (4 мс) — не ясно.** Минутки (шаг A, 566 монет): база %s в A и %s в B $/сут.; без 2 худших суток и монет знак «−» держится. Сделки, задержка 4 мс: база A %s, B %s (интервалы накрывают 0, без 2 худших суток A %s / B %s — знак «+») — «не ясно», как и топ-3 (%s) и оба варианта повторного входа; «опровергнуто» остаётся только при lat 0 (нереализуемом). Перекрёстный кандидат — 0 сделок на обоих шагах. Края нет, но и устойчивого минуса на сделках нет." % (
        n(A["long"]["cand"]["base"]["halves"]["A"]["mean"]), n(A["long"]["cand"]["base"]["halves"]["B"]["mean"]), n(lb0["A"]["mean"]), n(lb0["B"]["mean"]),
        n(lb0["A"]["no_worst2_days"]["mean"]), n(lb0["B"]["no_worst2_days"]["mean"]), tops("long")))
    w("- **Без 22 монет: прирост лонга на тиках — не находка (замечание проверки 14.11, п. 2).** " + ED.gain_note())
    for ln in ED.tgrid_bullet():
        w(ln)
    w("- **Шорт: опровергнуто на сделках (через половину B), на минутках — не ясно; шаги расходятся.** Минутки: база %s / %s (не ясно), перекрёстный %s / %s (не ясно). Сделки, задержка 4 мс: база A %s, B %s ([%s; %s]; без 2 худших суток %s, без 2 худших монет %s — знак держится, интервал накрывает 0), перекрёстный A %s / B %s (%s), топ-3 (семья be=0) — %s через B. Положительный знак минутной базы на сделках не воспроизводится (раздел «Почему шорт на минутках «+», на сделках «−»»)." % (
        n(A["short"]["cand"]["base"]["halves"]["A"]["mean"]), n(A["short"]["cand"]["base"]["halves"]["B"]["mean"]),
        n(A["short"]["cand"]["crossfit"]["halves"]["A"]["mean"]), n(A["short"]["cand"]["crossfit"]["halves"]["B"]["mean"]),
        n(sb0["A"]["mean"]), n(sb0["B"]["mean"]), n(sb0["B"]["lo"]), n(sb0["B"]["hi"]), n(sb0["B"]["no_worst2_days"]["mean"]), n(sb0["B"]["no_worst2_coins"]["mean"]),
        n(lt("short", "перекрёстный")["halves"]["A"]["mean"]), n(lt("short", "перекрёстный")["halves"]["B"]["mean"]), lt("short", "перекрёстный")["verdict"], tops("short").split("/")[0]))
    w("- **Против прежнего основного чтения (200 мс):** %s." % chg_txt)
    w("- **Повторный вход по уровню (§13.5, оба варианта) ничего не меняет:** повторы — 0–3 % сделок; вердикты те же (при 4 мс: лонг — не ясно, шорт база — опровергнуто), ни один кандидат не подтверждён.")
    w("- **Абсолютные аутсайдеры** найдены и перечислены (раздел ниже; полные списки — `docs/findings/p42-stats-and-outsiders-2026-11-14.md` §3); на тиках пересчитаны по клеткам 4 мс (%d клеток; прежний расчёт шёл по клеткам lat 0). В другой половине они не держатся: лонг на тиках — вместе %d из %d, p = %s; шорт — %d из %d, p = %s, после Бонферрони ×8 ≈ %s — не значимо%s. Исключение аутсайдеров базу не чинит (|Δ| ≤ $%s/сут., интервалы накрывают 0); список — не фильтр для бота без новых суток (найдено на этих данных)." % (
        ncell, pl["both"]["k"], pl["both"]["n"], MS.fp(pl["both"]["p"]), ps["both"]["k"], ps["both"]["n"], MS.fp(ps["both"]["p"]), MS.fp(ps["both"]["p_bonf"]),
        ("; при lat 0 было p = %s (≈ %s после Бонферрони)" % (MS.fp(old_s["both"]["p"]), MS.fp(old_s["both"]["p_bonf"]))) if old_s else "",
        n(max(abs(x["eval_delta"]) for x in EX), 2, False)))
    w("- **3,4 млн «плохих строк» aggTrades (0,6 %) выяснены:** это цены меньше 0,001 в записи `9.16E-4`; после правки разбора — 0 плохих строк, вердикты не изменились.\n")
    w("Числа — **измерено** на Binance USD-M. «Опровергнуто»/«не ясно» — по правилу §10 протокола `docs/research/P-42-level-breakout.md` (дополнен §13), Холм — по накопленному счётчику испытаний (" + (CHAIN or "лонг 207, шорт 199") + "; задержка 4 мс испытаний не добавляет). " + MCHECK + "Всё «найдено на этих данных»: ни одной проверки на новых сутках; демо-ожидание «после издержек», не прогноз.\n")

    w("## Протокол и данные")
    w("- Протокол: `docs/research/P-42-level-breakout.md` §13 (записан и закоммичен до счёта: `2356b172`; §13.5 «повторный вход» — `d1b86074` и `d24226a2`, тоже до счёта; §13.4 п. 8 «основное чтение — 4 мс» — `0f303188`, до счёта при 4 мс). Слова владельца 14.11: «надо грузить от 12 млн суточного объема»; «да давай для бинанса агтрейды»; про вариант с повторным входом — «ну сделай»; про задержку — «ну давай задержка будет 0.2», затем (В-157) %s." % OWNER157)
    w("- Универсум шага A: **566** бессрочных Binance USD-M с оборотом ≥ $12 млн хотя бы в один день 01.09–13.11 (227 прежних + 339 новых). Окна: прогрев 01.09–14.09, A 15.09–14.10, B 15.10–13.11 (по 30 суток).")
    w("- Шаг B: сделки `aggTrades` (`transact_time` в мс, цена как в файле), 566 монет; вход — следующая агрессивная сделка стороны (± 1 bp), тейки — только строго через цену, стоп — по цене пробившей сделки (§13.2); **основное исполнение — с задержкой 4 мс на вход и выход (`lat = latx = 4`, §13.4 п. 8, §13.6): вход и выход исполняются по первой сделке не раньше срабатывания + 4 мс; lat 0 — справочно (нереализуемо)**.")
    w("- Код: ветка `bb/42-v2-finish-v1-thr_7cy3ypv2kx` (от `bb/42-rerun-12m-ticks-v1-thr_fefbsq7ncj` @ e0539507); модуль `src/breakout/` (`tick.rs`, 1238 тестов, clippy `-D warnings`, fmt — зелёные на srv). Бинари на srv `/data/p42v2/bin/alpha-p42-v{5…11}` (счёт 4 мс — v11); результаты — `/data/p42v2/out/` (`tick-lx4/` — основное чтение), локально `data/p42v2/` (gitignored). Правки основного чтения (4 мс), отчёта и аутсайдеров — ветка `bb/42-stats-outsiders-v1-thr_ewewq28522`.\n")

    # ---------------- шаг A
    w("## Шаг A: минутки, 566 монет" + (" — справочно (§13.9: основной движок отбора — тики 4 мс, раздел 9)" if CHAIN else ""))
    for side in ("long", "short"):
        r = A[side]
        w("### %s" % SIDE[side])
        w("Испытаний шага A: %d (v1 %d + v2 %d); Холм по накопленному m = %d, z = %s; PBO %s (%d конфигураций)." % (
            r["m_package"], r["prior_trials"], r["trials"], r["m_package"], n(r["z_holm"], 2, False), n(r["pbo"]["pbo"], 2, False), r["pbo"]["configurations"]))
        names = [k for k in ("base", "crossfit", "letter") if k in r["cand"]]
        w(table_cands(r, [k for k in names if not (k == "letter" and r["cand"]["letter"]["verdict"] == r["cand"]["crossfit"]["verdict"] and r["cand"]["letter"]["halves"]["A"]["mean"] == r["cand"]["crossfit"]["halves"]["A"]["mean"])],
                      {"base": "база (правила витрины)", "crossfit": "перекрёстный (значения из другой половины)", "letter": "«по букве» протокола (справочно)"}))
        w("")
        b = r["cand"]["base"]["halves"]
        w("База: после первого дня монеты с оборотом ≥ $12 млн — A %s, B %s $/сут.; прежние 227 монет — A %s, B %s; новые 339 — A %s, B %s." % (
            n(b["A"]["after_first_day"]["mean"]), n(b["B"]["after_first_day"]["mean"]), n(b["A"]["old_coins"]), n(b["B"]["old_coins"]), n(b["A"]["new_coins"]), n(b["B"]["new_coins"])))
        w("Без 2 лучших суток: A %s, B %s; без 2 лучших монет: A %s, B %s.\n" % (
            n(b["A"]["no_best2_days"]["mean"]), n(b["B"]["no_best2_days"]["mean"]), n(b["A"]["no_best2_coins"]["mean"]), n(b["B"]["no_best2_coins"]["mean"])))

    # ---------------- шаг B, lat 0
    w("## Шаг B: вход и выходы по сделкам — справочно: lat 0 (нереализуемо)")
    w("**Таблицы этого раздела — справочно: lat 0** (вход — следующая агрессивная сделка стороны, 55–64 % входов в ту же миллисекунду, что сделка-сигнал; реагирующий ордер так не исполняется — нереализуемо). Предрегистрированное чтение §13.2; основное чтение — задержка 4 мс на входы и выходы, см. раздел «Основное чтение» ниже (§13.4 п. 8, В-157).\n")
    tm = {"base": "тик-база (lat 0, 1 bp)", "crossfit": "тик-перекрёстный (lat 0)", "top:v_n_bounce_3": "топ-3: n_bounce=3 (lat 0)", "top:v_e_0p1": "топ-3: e=0,1 (lat 0)",
          "top:v_tf_240": "топ-3: tf=240 (lat 0)", "top:j_be_0__t_low_2": "топ-3: be=0, t_low=2 (lat 0)", "top:v_be_0": "топ-3: be=0 (lat 0)", "top:j_be_0__t_low_3": "топ-3: be=0, t_low=3 (lat 0)"}
    for side in ("long", "short"):
        r = T[side]
        w("### %s (справочно: lat 0)" % SIDE[side])
        w("Испытаний шага B: %d (база 1 + перекрёстный 2 + топ-3); накопленный m = %d (шаг A %d), z Холма = %s. Топ-3 — отбор на тех же данных («найдено на этих данных»), справочно." % (
            r["n_step_b"], r["m"], r["m_step_a"], n(r["z_holm"], 2, False)))
        w(table_cands(r, list(r["cand"].keys()), tm))
        w("")
        w("Задержка входа и проскальзывание (справочно, не испытания; $/сут., [95 %], сделок):")
        w("")
        w("| вариант | A | B |")
        w("|---|---|---|")
        for k, v in r["sens"].items():
            if v["statA"]["trades"] == 0 and v["statB"]["trades"] == 0:
                continue
            nm = k.replace("b0_", "база ").replace("cross_", "перекрёстный ").replace("lat", "задержка ").replace("slip", "проскальзывание ")
            w("| %s | %s [%s; %s], n=%d | %s [%s; %s], n=%d |" % (nm, n(v["A"]), n(v["statA"]["lo"]), n(v["statA"]["hi"]), v["statA"]["trades"], n(v["B"]), n(v["statB"]["lo"]), n(v["statB"]["hi"]), v["statB"]["trades"]))
        w("")
    w("**Минутки против сделок (база, lat 0).** Сделок в 3–4 раза больше (лонг A: 86 → 344, B: 106 → 373; шорт A: 76 → 311, B: 70 → 313), потому что сигнал стоит на первом подходе в зону внутри минутки — в том числе в минутках, которые потом пересекают уровень (1м такие пропускает). Шорт на минутках около нуля (%s / %s), на сделках при lat 0 — минус, особенно в B (%s): доля стопов шорта выросла с %.1f %% / %.1f %% (1м, A/B) до 9 %% / 17 %% (сделки). Пример из разбора предыдущего прогона (TAKEUSDT, не пересчитан): вход по нижней сделке «флеш-вика» (свип 5 %% за 1 мс), стоп через 1 мс, −$25 — артефакт нулевой задержки; при задержке 250/1000 мс шорт-убыток в B сокращается до %s / %s, но знак остаётся отрицательным." % (
        n(A["short"]["cand"]["base"]["halves"]["A"]["mean"]), n(A["short"]["cand"]["base"]["halves"]["B"]["mean"]), n(sb["mean"]),
        A["short"]["cand"]["base"]["halves"]["A"]["stop_share"] * 100, A["short"]["cand"]["base"]["halves"]["B"]["stop_share"] * 100,
        n(T["short"]["sens"]["b0_lat250"]["B"]), n(T["short"]["sens"]["b0_lat1000"]["B"])))
    w("Лонг при задержке 250/1000 мс: A %s / %s, B %s / %s — интервалы накрывают 0, знак «−» во всех клетках; при проскальзывании 0 → 5 bp база лонга %s → %s в A.\n" % (
        n(T["long"]["sens"]["b0_lat250"]["A"]), n(T["long"]["sens"]["b0_lat1000"]["A"]), n(T["long"]["sens"]["b0_lat250"]["B"]), n(T["long"]["sens"]["b0_lat1000"]["B"]),
        n(T["long"]["sens"]["b0_slip0"]["A"]), n(T["long"]["sens"]["b0_slip5"]["A"])))

    # ---------------- основное чтение: задержка 4 мс
    tr4 = {s: list(_csv.DictReader(open(os.path.join(ROOT, "tick-lx4", "b0_lx4", s + "-trades.csv"), encoding="utf-8"))) for s in ("long", "short")}
    same4 = {s: sum(1 for t in tr4[s] if t["entry_ms"] == t["sig_ms"]) for s in tr4}
    w("## Основное чтение: задержка 4 мс на входы и выходы (§13.4 п. 8, В-157; §13.6)")
    w("- **Отклонение протокола (§13.4 п. 8).** Основное чтение шага B менялось дважды: lat 0 (предрегистрация §13.2) → 200 мс (§13.4 п. 6, слова владельца «ну давай задержка будет 0.2») → **4 мс по слову владельца (В-157, 14.11 ≈ 23:10, дословно): %s**. Смена — после счёта шага B, по слову владельца, а не по результату; запись в протокол сделана до счёта при 4 мс (коммит `0f303188`). Величина 4 мс — параметр модели, названная владельцем; испытаний не добавляет (Холм m: лонг 207, шорт 199). 200 / 250 / 1000 мс и lat 0 — справочно." % OWNER157)
    w("- **Почему не lat 0.** При lat 0 вход — следующая агрессивная сделка стороны, часто в ту же миллисекунду, что сделка-сигнал: лонг A 189/344, B 198/373; шорт A 199/311, B 187/313 (55–64 %%) — внутри чужой серии рыночных заявок, реагирующий ордер так не исполняется. Шорт B: эти входы несут −$640 из −$778 за половину. При 4 мс входов в ту же миллисекунду, что сигнал: лонг %d из %d, шорт %d из %d. Задержка была предрегистрирована как справочная ось (§13.2 п. 5)." % (same4["long"], len(tr4["long"]), same4["short"], len(tr4["short"])))
